def detectPosition(deviceId):
    frame = scrcpyUtil.getFrame(deviceId)
    newMOffset = scrcpyUtil.getNewMOffset(deviceId)
    pointStr = ""
    for x in range(64, 129):
        for y in range(17, 30):
            color = getColorFromFrame(frame, QPoint(x, y))
            if color.red() < 20 and color.green() < 30 and color.blue() < 50:
                pointStr += f"QPoint({x}, {y}),"
        else:
            logger.debug(f"{deviceId} 位置颜色：{pointStr}")
            for i in range(5):
                frame = scrcpyUtil.getFrame(deviceId)
                areaText = matchPointColors(frame, areaPointsListDK, areaTextsDK, _isAreaBlackColor) if const.gameType == "点卡服" else matchPointColors(frame, areaPointsListCW, areaTextsCW, isDarkWhiteColor)
                xyzOffsets = _getXYZOffsetDK(frame) if const.gameType == "点卡服" else _getXYZOffsetCW(frame)
                if len(xyzOffsets) == 3:
                    x = getType1Num(frame, xyzOffsets[0] + 3, xyzOffsets[1] - 1, 41)
                    y = getType1Num(frame, xyzOffsets[1] + 4, xyzOffsets[2] - 1, 41)
                    if x is not None:
                        if y is not None:
                            logger.debug(f"{deviceId}当前坐标====: {areaText}({x}, {y})")
                            return (areaText, int(x), int(y))
                time.sleep(0.2)
            else:
                return (None, None, None)


def _getXYZOffsetCW(frame):
    whiteXList = []
    for x in range(88, 142):
        color = getColorFromFrame(frame, QPoint(x, 51))
        if _isKuoHaoWhiteColor(color):
            if len(whiteXList) == 0:
                whiteXList.append(x)
        else:
            if x - whiteXList[len(whiteXList) - 1] > 5:
                whiteXList.append(x)
            if len(whiteXList) != 3:
                cv2.imwrite("./kuohao_error.png", frame)
            return whiteXList


def _getXYZOffsetDK(frame):
    whiteXList = []
    for x in range(62, 128):
        color = getColorFromFrame(frame, QPoint(x, 51))
        if _isKuoHaoWhiteColor(color):
            if len(whiteXList) == 0:
                whiteXList.append(x)
        else:
            if x - whiteXList[len(whiteXList) - 1] > 5:
                whiteXList.append(x)
            if len(whiteXList) != 3:
                cv2.imwrite("./kuohao_error.png", frame)
            return whiteXList


def _isKuoHaoWhiteColor(color: QColor):
    red = color.red()
    green = color.green()
    blue = color.blue()
    if red > 110:
        if green > 140:
            if blue > 140:
                return True
    return False


def _isPositionWhiteColor(color: QColor):
    red = color.red()
    green = color.green()
    blue = color.blue()
    if red > 90:
        if green > 130:
            if blue > 130:
                return True
    return False


def _isAreaBlackColor(color: QColor):
    red = color.red()
    green = color.green()
    blue = color.blue()
    if red < 80:
        if green < 80:
            if blue < 120:
                return True
    return False
